struct Version { fee: Decimal, terms: String }          // plain owned value, cloned to publish
struct Contract { id: ContractId, history: Vec<(NaiveDate, Version)> }   // ascending
impl Contract {
    fn as_of(&self, on: NaiveDate) -> Option<&Version> {
        let i = self.history.partition_point(|(eff, _)| *eff <= on);
        i.checked_sub(1).map(|k| &self.history[k].1)        // None = Missing Version
    }
    fn amend(&mut self, effective: NaiveDate, working: Version) {
        let at = self.history.partition_point(|(eff, _)| *eff <= effective);
        self.history.insert(at, (effective, working));      // retroactive or scheduled
    }
}

