type Effective = i64;                                  // seconds since UNIX_EPOCH, UTC
struct Contract { history: Vec<(Effective, Version)> } // ascending

impl Contract {
    fn as_of(&self, on: SystemTime) -> Option<&Version> {
        let t = on.duration_since(UNIX_EPOCH).ok()?.as_secs() as i64;
        let i = self.history.partition_point(|(eff, _)| *eff <= t);
        i.checked_sub(1).map(|k| &self.history[k].1)
    }
}
